const districtById = new Map(DISTRICTS.map((d) => [d.id, d]));
const stateById = new Map(STATES.map((s) => [s.id, s]));

export function getDistrict(id: string): District | undefined {
  return districtById.get(id);
}
export function districtName(id: string): string {
  return districtById.get(id)?.name ?? id;
}
export function stateName(id: string): string {
  return stateById.get(id)?.name ?? id;
}
export function districtsOf(stateId: string): District[] {
  return DISTRICTS.filter((d) => d.stateId === stateId);
}
export function stateOfDistrict(districtId: string): string {
  return districtById.get(districtId)?.stateId ?? STATES[0].id;
}
